import AppKit

// Real product brand mark (two image frames + exchange arrows),
// embedded as base64 so it renders identically in dev (bare `swift
// run` executable, no .app bundle) and in the packaged/codesigned
// .app. Byte-for-byte the web logo (frontend/public/logo-192.png).
// Used by the sidebar logo chip, the status-bar item, and the
// programmatic Dock icon — none of which can rely on Bundle.main in
// a dev build.
enum BrandAsset {
    static let logo: NSImage? = {
        guard let data = Data(base64Encoded: logoBase64) else { return nil }
        return NSImage(data: data)
    }()

    // Composed Dock icon for dev builds: a white rounded-square body with
    // the brand mark shrunk and centred — matches the bundled
    // AppIcon.icns. Sidebar / status-bar keep the raw transparent `logo`;
    // only the Dock uses this white-square form.
    static let dockIcon: NSImage? = {
        guard let mark = logo else { return nil }
        let s: CGFloat = 512
        let img = NSImage(size: NSSize(width: s, height: s))
        img.lockFocus()
        let margin = s * (100.0 / 1024.0)
        let body = NSRect(x: margin, y: margin, width: s - 2 * margin, height: s - 2 * margin)
        let r = s * (180.0 / 1024.0)
        NSColor.white.setFill()
        NSBezierPath(roundedRect: body, xRadius: r, yRadius: r).fill()
        let l = s * 0.52
        mark.draw(in: NSRect(x: (s - l) / 2, y: (s - l) / 2, width: l, height: l),
                  from: .zero, operation: .sourceOver, fraction: 1)
        img.unlockFocus()
        return img
    }()

    private static let logoBase64 = ""
}
